/* ---- ../cat/art.js ---- */
'use strict';
/* 極簡扁平風的貓,照著使用者提供的參考圖。
   走路、坐下都用 tools/trace_refs.js 從參考圖描出的向量(traced.js),睡覺是照參考圖手描的 SVG 路徑。
   座標是參考圖的像素(約 1024 寬),再縮小成遊戲單位。沒有輪廓線,遠側部位用同色稍深。 */
const ART={};
(function(){
let c,K,BLINK;
const SC=.1,WALK_FPS=5;

/* ===== 側面、正面、背面:直接用參考圖描出的向量(src/cat/traced.js),依花色重新上色 ===== */
const TP={};const tp=d=>TP[d]||(TP[d]=new Path2D(d));
/* 賓士:所有動作都用同一套白色部位——白口鼻、白胸口(圍兜)、四隻白腳掌,其餘全黑(尾巴也是黑的)。
   位置依各姿勢的臉(眼睛)與腳來放;沒有偵測到眼睛的側面走路用固定的位置。 */
const TUX_FACE={sideWalk:{mx:-312,my:-318,cx:-270,cy:-262,crx:38,cry:82},lie:{bib:true}};
function tuxedoMarks(T,pose){
  const ell=(x,y,rx,ry,rot=0)=>{c.beginPath();c.ellipse(x,y,rx,ry,rot,0,Math.PI*2);c.fill();};
  const sock=(x0,x1,h)=>c.fillRect(x0-6,-h,x1-x0+12,h);
  const face=TUX_FACE[pose];
  if(face&&face.bib){
    // 趴著:白色從嘴巴往下延伸到下巴、胸口,再接到前腳掌,連成一片
    c.beginPath();c.moveTo(-232,-72);
    c.bezierCurveTo(-222,-96,-160,-98,-148,-70);
    c.bezierCurveTo(-140,-50,-130,-36,-110,-30);
    c.bezierCurveTo(-110,-14,-120,0,-140,0);
    c.lineTo(-285,0);c.bezierCurveTo(-285,-24,-250,-40,-232,-72);c.fill();
  }else if(face){ell(face.mx,face.my,face.mrx||30,face.mry||22);if(face.cx!==undefined)ell(face.cx,face.cy,face.crx,face.cry,-.35);}
  else if(T.eyes&&T.eyes.length){
    const xs=T.eyes.map(e=>(e.b[0]+e.b[2])/2),cx=xs.reduce((a,b)=>a+b)/xs.length,ey=Math.max(...T.eyes.map(e=>e.b[3]));
    ell(cx,ey+30,46,34);                                      // 口鼻
    ell(cx,ey+150,52,96);                                     // 胸口
  }
  const bw=T.box[2]-T.box[0];
  if(pose==='sideSit')sock(T.box[2]-bw*.34,T.box[2],44);      // 坐姿只看得到前腳掌
  else if(pose==='sideSitL')sock(T.box[0],T.box[0]+bw*.34,44);
  else if(pose==='frontSit')sock(-bw*.2,bw*.2,44);
  else if(pose==='lie'){}                                            // 趴著:前腳掌已包含在白色圍兜裡
  else if(pose!=='backSit')T.feet.forEach(f=>sock(f[0],f[1],60));   // 走路:每隻腳都是白腳掌
}
/* 三花、乳牛:所有動作用同一套花紋——頭頂與耳朵一塊、背上兩塊斑、尾巴、尾尖。
   位置依各姿勢手動標定(參考圖的座標,腳底中心為原點)。
   三花:頭頂橘、背上一橘一黑、尾巴橘、尾尖黑。乳牛:頭頂黑、背上兩塊黑、尾巴黑。 */
const e=(x,y,rx,ry)=>['e',x,y,rx,ry],rr=(x0,y0,x1,y1)=>['r',x0,y0,x1,y1];
const MARKS={
  sideSit:{cap:e(120,-505,100,60),spots:[e(-30,-300,55,45),e(-110,-160,45,55)],tailPo:rr(-175,-60,60,0),tip:e(-160,-22,26,22)},
  sideSitL:{cap:e(-101,-505,100,60),spots:[e(49,-300,55,45),e(129,-160,45,55)],tailPo:rr(-41,-60,194,0),tip:e(179,-22,26,22)},
  sideWalk:{cap:e(-240,-420,90,55),spots:[e(-110,-300,55,40),e(60,-320,75,45)],tailPo:rr(262,-260,400,-80),tip:e(355,-110,30,25)},
  backSit:{cap:e(-47,-545,100,65),spots:[e(-100,-270,45,40),e(40,-200,50,45)],tail:[e(100,-35,60,38)],tip:e(125,-30,20,18)},
  frontSit:{cap:e(-55,-520,100,55),spots:[e(-165,-250,35,50),e(75,-280,30,45)],tail:[e(120,-35,50,34)],tip:e(145,-30,22,20)},
  frontStand:{cap:e(-5,-525,95,50),spots:[e(-75,-260,30,45),e(60,-200,28,40)],tail:[rr(-30,-650,20,-500)],tip:e(-5,-615,20,25)},
  lie:{cap:e(-215,-190,85,55),spots:[e(-10,-205,70,40),e(170,-190,60,45)],tailPo:rr(-40,-90,300,0),tip:e(250,-40,25,25)},
  backStand:{cap:e(-55,-550,95,60),spots:[e(-75,-330,50,45),e(60,-230,50,50)],tail:[rr(40,-600,105,-430)],tip:e(72,-585,25,25)},
};
function shape(m){c.beginPath();if(m[0]==='e')c.ellipse(m[1],m[2],m[3],m[4],0,0,Math.PI*2);else c.rect(m[1],m[2],m[3]-m[1],m[4]-m[2]);c.fill();}
function spotMarks(T,pose,P){
  const M=MARKS[pose];if(!M)return;
  const dark=cssc(K.spot[0]),light=P==='calico'?cssc(K.spot[1]):dark;
  c.fillStyle=light;shape(M.cap);
  c.fillStyle=light;shape(M.spots[0]);c.fillStyle=dark;shape(M.spots[1]);
  if(M.tailPo&&T.po){
    // 尾巴貼著身體時,用參考圖裡描出的橘色尾巴形狀(限定在尾巴的範圍內)
    const b=M.tailPo;c.save();c.beginPath();c.rect(b[1],b[2],b[3]-b[1],b[4]-b[2]);c.clip();c.clip(tp(T.po),'evenodd');
    c.fillStyle=light;c.fillRect(b[1],b[2],b[3]-b[1],b[4]-b[2]);
    if(P==='calico'){c.fillStyle=dark;shape(M.tip);}
    c.restore();
  }else if(M.tail){
    c.fillStyle=light;M.tail.forEach(shape);
    if(P==='calico'){c.fillStyle=dark;shape(M.tip);}
  }
}
function tracedLayers(T,pose){
  const sil=tp(T.sil);
  c.fillStyle=cssc(K.base);c.fill(sil);
  c.save();c.clip(sil);
  if(T.shade){c.fillStyle=cssc(K.base,K.farK);c.fill(tp(T.shade),'evenodd');}
  if(T.shade2){c.fillStyle=cssc(K.base,.94);c.fill(tp(T.shade2),'evenodd');}
  const P=K.pattern;
  if(P==='cow'&&T.ck){
    // 乳牛:有乳牛參考圖(sheet3)的姿勢,直接用描出的黑斑
    c.fillStyle=cssc(K.spot[0]);c.fill(tp(T.ck),'evenodd');
  }else if((P==='calico'||P==='cow')&&pose!=='backStand'){
    // 三花以使用者指定的參考圖花紋為準:直接用描出的橘色、黑色色塊;乳牛用同樣的色塊形狀,全部塗黑
    if(T.po){c.fillStyle=cssc(K.spot[1]);c.fill(tp(T.po),'evenodd');}
    if(T.pk){c.fillStyle=cssc(K.spot[0]);c.fill(tp(T.pk),'evenodd');}
  }else if(P==='calico'||P==='cow')spotMarks(T,pose,P);
  if(P==='tuxedo'){c.fillStyle=cssc(K.spot[0]);tuxedoMarks(T,pose);}
  c.restore();
  // 臉
  if(T.eyes){
    if(BLINK<.5){
      c.strokeStyle='rgb(30,26,26)';c.lineWidth=5;c.lineCap='round';
      T.eyes.forEach(({b})=>{const y=(b[1]+b[3])/2;c.beginPath();c.moveTo(b[0],y);c.quadraticCurveTo((b[0]+b[2])/2,y+10,b[2],y);c.stroke();});
    }else{
      c.fillStyle=cssc(K.eye);T.eyes.forEach(e=>c.fill(tp(e.d)));
      if(T.pupil){c.fillStyle='rgb(22,18,18)';c.fill(tp(T.pupil),'evenodd');}
    }
  }
  if(T.nose){c.fillStyle=cssc(K.nose);c.fill(tp(T.nose),'evenodd');}
  if(T.ink){c.fillStyle=K.dark?'rgba(236,236,236,.9)':'rgb(26,22,22)';c.fill(tp(T.ink),'evenodd');}
}
/** lift:0=站好;1、2=抬起第幾隻腳(走路的跨步格) */
function drawTraced(pose,lift){
  // lift:0=站好;1=抬起第 1、3…隻腳;2=抬起第 2、4…隻腳(走路的跨步格)
  const T=TRACED[pose];
  if(!lift||!T.feet||T.feet.length<2){tracedLayers(T,pose);return;}
  const feet=T.feet.filter((_,i)=>i%2===lift-1),cut=-110,up=22;
  c.save();c.beginPath();c.rect(-2000,-2000,4000,4000);feet.forEach(f=>c.rect(f[0]-10,cut,f[1]-f[0]+20,300));c.clip('evenodd');tracedLayers(T,pose);c.restore();
  c.save();c.beginPath();feet.forEach(f=>c.rect(f[0]-10,cut-4,f[1]-f[0]+20,304));c.clip();c.translate(0,-up);tracedLayers(T,pose);c.restore();   // 往上多蓋 4px,消掉切口的細縫
}


/** 影子要對準的水平位置(貓的單位):描出的姿勢依外框中心 */
ART.centerX=function(o){
  const side=o.dir==='left'||o.dir==='right';
  const pose=o.act==='sleep'?'lie':o.act==='sit'?(side?(o.dir==='left'?'sideSitL':'sideSit'):o.dir==='down'?'frontSit':'backSit'):o.act==='walk'?(side?'sideWalk':o.dir==='down'?'frontStand':'backStand'):null;
  if(!pose||!TRACED[pose])return 0;
  const b=TRACED[pose].box,cx=(b[0]+b[2])/2*SC;
  return (pose==='sideWalk'||pose==='lie')&&o.dir==='right'?-cx:cx;
};
/** 入口:在 (0,0)=腳底中心畫一隻貓 */
ART.draw=function(ctx,o){
  c=ctx;K=COATS[o.coat||'orange'];BLINK=o.blink===undefined?1:o.blink;
  // 走路只用 3 張圖、4 格循環:站姿 → 跨步 A → 站姿 → 跨步 B(每格約 0.2 秒),像精靈圖一樣切換
  const t=o.t||0,frame=Math.floor(t*WALK_FPS)%4,ph=frame*Math.PI/2,tw=Math.floor(t*WALK_FPS)*.9,side=(o.dir==='left'||o.dir==='right')&&o.act!=='sleep';
  c.save();
  // 高俯角:略為壓扁;squash 可由呼叫端指定(視角切換時平滑變化)
  c.scale(1,o.squash!==undefined?o.squash:(o.pitch>15?.93:1));
  c.scale(SC,SC);
  if(side&&o.act==='sit'){
    drawTraced(o.dir==='left'?'sideSitL':'sideSit',0);        // 兩個方向都有各自的參考圖
  }else if(side){
    if(o.dir==='right')c.scale(-1,1);                         // 側面走路的參考圖朝左,朝右時鏡像
    drawTraced('sideWalk',frame===1?1:frame===3?2:0);
  }else if(o.act==='sleep'){
    if(o.dir==='right')c.scale(-1,1);                         // 趴下的參考圖朝左,朝右時鏡像
    const br=1+Math.sin(t*1.6)*.012;c.scale(1,br);            // 呼吸時微微起伏
    drawTraced('lie',0);
  }else{
    if(o.act==='sit')drawTraced(o.dir==='down'?'frontSit':'backSit',0);
    else drawTraced(o.dir==='down'?'frontStand':'backStand',frame===1?1:frame===3?2:0);
  }
  c.restore();
};
})();

/* ---- ../cat/cat.js ---- */
'use strict';
/* 貓咪入口:drawCat(c,{dir,act,pitch,t,coat,blink})
   在 (0,0)=腳底中心繪製。dir: left|right|up|down;act: walk|sit;pitch: 俯角(度) */
const CAT_POSES=[
  {dir:'left',act:'walk'},{dir:'right',act:'walk'},{dir:'up',act:'walk'},{dir:'down',act:'walk'},
  {dir:'left',act:'sit'},{dir:'right',act:'sit'},{dir:'up',act:'sit'},{dir:'down',act:'sit'},
  {dir:'left',act:'sleep'},{dir:'right',act:'sleep'},
];
const CAT_LABEL={left:'左',right:'右',up:'背對',down:'面對'};
const ACT_LABEL={walk:'走路',sit:'坐下',sleep:'趴下'};
function drawCat(c,o){ART.draw(c,o);}

/* ---- main.js ---- */
'use strict';
/* 預覽頁:花色切換、走路/坐下 × 4 方向 × 2 視角,可匯出 PNG 圖集 */
const CW=220,CH=230,DPR=2,SC=1.5,PITCHES=[{p:30,n:'高俯角 30°'},{p:6,n:'近距離'}];
let coatKey='orange';
const cards=[];
const wrap=document.getElementById('grid'),bar=document.getElementById('coats');

Object.entries(COATS).forEach(([k,v])=>{
  const b=document.createElement('button');b.textContent=v.name;b.dataset.k=k;
  b.onclick=()=>{coatKey=k;[...bar.children].forEach(x=>x.classList.toggle('on',x.dataset.k===k));};
  bar.appendChild(b);
});
bar.children[0].classList.add('on');

PITCHES.forEach(pt=>{
  const h=document.createElement('h2');h.textContent=pt.n;wrap.appendChild(h);
  const g=document.createElement('div');g.className='g';wrap.appendChild(g);
  CAT_POSES.forEach(po=>{
    const d=document.createElement('div');d.className='card';
    d.innerHTML=`<canvas width="${CW*DPR}" height="${CH*DPR}"></canvas><div class="t"><b>${ACT_LABEL[po.act]}・${CAT_LABEL[po.dir]}</b></div>`;
    g.appendChild(d);
    cards.push({...po,pitch:pt.p,c:d.querySelector('canvas').getContext('2d')});
  });
});

function backdrop(c,pitch){
  const sn=Math.sin(pitch*Math.PI/180),oy=CH-34;
  c.fillStyle='#d9eef7';c.fillRect(0,0,CW,CH);
  const yh=oy-Math.max(12,120*sn);
  c.fillStyle='#8ed05e';c.fillRect(0,yh,CW,CH-yh);
  const th=Math.max(6,40*sn);
  for(let r=0,y=yh;y<CH;r++,y+=th)for(let x=0,i=0;x<CW;x+=40,i++){c.fillStyle=(i+r)%2?'#8ed05e':'#98dc68';c.fillRect(x,y,41,th+1);}
  c.fillStyle='rgba(30,70,20,.25)';c.beginPath();c.ellipse(CW/2,oy,38*SC,Math.max(3,14*sn*SC),0,0,7);c.fill();
}
function frame(ms){
  const t=ms/1000,blink=(t%3.6)<.14?.15:1;
  cards.forEach(k=>{
    const c=k.c;c.setTransform(DPR,0,0,DPR,0,0);
    backdrop(c,k.pitch);
    c.save();c.translate(CW/2,CH-34);c.scale(SC,SC);
    drawCat(c,{dir:k.dir,act:k.act,pitch:k.pitch,t,coat:coatKey,blink});
    c.restore();
  });
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

/* 匯出透明背景圖集:每列 = 視角×動作×方向,走路 8 格、坐下 4 格 */
function exportSheet(key){
  const CELL_W=320,CELL_H=300,S=2,rows=[];
  PITCHES.forEach(pt=>CAT_POSES.forEach(po=>rows.push({...po,pitch:pt.p})));
  const cols=8,cv=document.createElement('canvas');cv.width=cols*CELL_W;cv.height=rows.length*CELL_H;
  const c=cv.getContext('2d');
  rows.forEach((r,ri)=>{
    const n=4;   // 走路:站姿、跨步 A、站姿、跨步 B
    for(let i=0;i<n;i++){
      c.save();c.translate(i*CELL_W+CELL_W/2,ri*CELL_H+CELL_H-40);c.scale(S,S);
      const t=(i+.5)/5;
      drawCat(c,{dir:r.dir,act:r.act,pitch:r.pitch,t,coat:key});
      c.restore();
    }
  });
  const a=document.createElement('a');a.href=cv.toDataURL('image/png');a.download=`cat_${key}_sheet.png`;a.click();
  return {w:cv.width,h:cv.height,rows:rows.length};
}
document.getElementById('exp').onclick=()=>exportSheet(coatKey);
